#!/usr/bin/env node
// Builds dist/rse.js — every component on window.RSE, for pages with no build step.
//
//   node scripts/build-bundle.mjs          # write
//   node scripts/build-bundle.mjs --check  # exit 1 if dist/rse.js is not what the sources produce
//
// The bundle is a copy, not a compile: components are written in React.createElement form on
// purpose, so no JSX transform is needed and a component written with JSX tags is rejected.
// It is regenerated whole from the manifest every time, so it cannot drift or keep dead code.
// React itself is not inside: load React 18 UMD first (assets/vendor/ has it).

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');
const OUT = 'dist/rse.js';
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const manifest = JSON.parse(read('rse.manifest.json'));
const pkg = JSON.parse(read('package.json'));

const hasJsx = (src) =>
  src.split('\n').some((l) => /^\s*(return\s*\(|<[A-Z])/.test(l) && /<[A-Za-z][\w.]*[\s/>]/.test(l));

// 'use client' must sit above the imports in the source (Next.js App Router); inside the bundle's
// IIFE it is meaningless and a bare `import` is a syntax error, so both go.
// A component may import another (Modal uses Icon): `import { Icon } from '../core/Icon.jsx'`
// becomes a read from the shared scope, and blocks are ordered so dependencies come first.
const INTERNAL_IMPORT = /^import \{([^}]+)\} from '\.\.?\/(?:[a-z]+\/)?([A-Za-z]+)\.jsx';\r?\n/gm;
const toBundleForm = (src) =>
  src
    .replace(/^(['"])use client\1;?\r?\n/, '')
    .replace(/^import React from 'react';\n/, '')
    .replace(INTERNAL_IMPORT, (_, names) => `const {${names}} = scope;\n`)
    .replace(/^export (function|const) /gm, '$1 ')
    .trimEnd();

let failed = false;
const exported = [];
let body = '';
const byName = new Map(manifest.components.map((c) => [c.name, c]));
const depsOf = (c) => existsSync(join(ROOT, c.sourcePath))
  ? [...read(c.sourcePath).matchAll(INTERNAL_IMPORT)].map((m) => m[2]).filter((n) => byName.has(n))
  : [];
const ordered = [];
const visit = (c, stack = []) => {
  if (ordered.includes(c)) return;
  if (stack.includes(c)) { console.error(`import cycle: ${[...stack, c].map((x) => x.name).join(' → ')}`); process.exit(1); }
  for (const d of depsOf(c)) visit(byName.get(d), [...stack, c]);
  ordered.push(c);
};
manifest.components.forEach((c) => visit(c));
for (const c of ordered) {
  if (!existsSync(join(ROOT, c.sourcePath))) { console.error(`missing source ${c.sourcePath}`); failed = true; continue; }
  const src = read(c.sourcePath);
  if (hasJsx(src)) { console.error(`${c.sourcePath}: written with JSX — use React.createElement form.`); failed = true; continue; }
  const names = [...src.matchAll(/^export (?:function|const) ([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]);
  exported.push(...names);
  body += `\n// ${c.sourcePath}\ndefine(${JSON.stringify(c.sourcePath)}, ${JSON.stringify(names)}, () => {\n${toBundleForm(src)}\nreturn { ${names.join(', ')} };\n});\n`;
}
if (failed) process.exit(1);

// Each block must parse on its own: a syntax error in one component would otherwise take every
// component on the page down with it, and only a browser would notice.
for (const c of ordered) {
  try { new Function('React', 'scope', 'RSE', toBundleForm(read(c.sourcePath)) + '\nreturn {};'); }
  catch (e) { console.error(`${c.sourcePath}: ${e.message}`); failed = true; }
}
if (failed) process.exit(1);

const out = `/* GENERATED by scripts/build-bundle.mjs — do not edit. Run \`npm run sync\`.
   ${pkg.name}@${pkg.version} — every component on window.RSE. Needs React 18 (UMD) on the page by
   the time a component is first used; the bundle itself may load before it. */
(() => {
const RSE = (window.RSE = window.RSE || {});
RSE.__errors = RSE.__errors || [];
RSE.version = ${JSON.stringify(pkg.version)};
// Each component is evaluated the first time it is read, so React (and forwardRef) only has to
// exist when a page renders, not when this file loads. A component that fails to evaluate is
// recorded in RSE.__errors and reads as undefined; the others still work.
const scope = {};
const factories = {};
const cache = {};
const load = (path) => {
  if (!cache[path]) {
    try { cache[path] = factories[path](); }
    catch (e) { cache[path] = {}; RSE.__errors.push({ path, error: String((e && e.message) || e) }); }
  }
  return cache[path];
};
const define = (path, names, factory) => {
  factories[path] = factory;
  for (const name of names) {
    const get = () => load(path)[name];
    Object.defineProperty(scope, name, { get, enumerable: true, configurable: true });
    Object.defineProperty(RSE, name, { get, enumerable: true, configurable: true });
  }
};
${body}
})();
`;

const current = existsSync(join(ROOT, OUT)) ? read(OUT) : null;
if (current === out) { console.log(`bundle up to date (${manifest.components.length} components)`); process.exit(0); }
if (checkOnly) { console.log(`${OUT} is out of date — run \`npm run sync\``); process.exit(1); }
mkdirSync(join(ROOT, 'dist'), { recursive: true });
writeFileSync(join(ROOT, OUT), out);
console.log(`wrote ${OUT} (${manifest.components.length} components, ${exported.length} exports)`);
